const input = $input.first().json.text;

let parsed;
try {
    parsed = JSON.parse(input);
} catch (e) {
    throw new Error("JSON parsing error: " + e.message);
}

return [{ json: parsed }];

// Берём все элементы из предыдущего узла
let allItems = $input.all();

let result = allItems.map(item => {
    if (item.json.data) {
        let text = item.json.data;

        // 1. Убираем все переносы строк
        text = text.replace(/\r?\n/g, " ");

        // 2. Убираем все кавычки, обратные слэши и символы Markdown
        text = text.replace(/[\"\'\\#*\-`>\[\]_]/g, "");

        // 3. Убираем двойные пробелы
        text = text.replace(/\s{2,}/g, " ");

        // 4. Убираем пробелы в начале/конце
        text = text.trim();

        // 5. Присваиваем обратно
        item.json.data = text;
    }
    return item;
});

// Возвращаем результат
return result;

// Берём все элементы из предыдущего узла
let items = $input.all(); // если предыдущий узел передает несколько элементов

// Собираем все значения ключа 'data' в один массив
let allData = items.map(item => item.json.data);

// Если нужно вернуть как один объект для следующего узла
return [
  {
    json: {
      combinedData: allData
    }
  }
];

const allItems = $input.all();
let finalText = allItems
    .map(item => item.json.text)
    .filter(Boolean)
    .join(" ");  // соединяем все тексты

return [
  {
    json: {
      text: finalText
    }
  }
];

// Берём текст из входного item
let text = $json.text || "";

// Убираем переносы строк и пробелы в начале/конце
text = text.replace(/\r?\n/g, " ").trim();

// Возвращаем как json с полем text
return [
  {
    json: {
      text: text
    }
  }
];

// Берём текст из входного item
let text =  $input.first().json.message.text || "";

// Убираем переносы строк и пробелы в начале/конце
text = text.replace(/\r?\n/g, " ").trim();

// Возвращаем как json с полем text
return [
  {
    json: {
      text: text
    }
  }
];

const lessons = items;

// Завтра
const tomorrow = $now.plus({ days: 1 });

// День недели (1 = Пн ... 7 = Вс)
const weekday = tomorrow.weekday;

let text = "📚 Расписание на завтра:\n\n";

// ---- добавляем всё, что пришло из Excel ----
for (const item of lessons) {
  const row = item.json;

  text += `⏰ ${row["Время"]}\n`;
  text += `📖 ${row["Дисциплина"]}\n`;
  text += `🏫 ${row["Аудитория"]}\n\n`;
}

// ---- если завтра суббота — добавляем фиксированный текст ----
if (weekday === 6) {  // 6 = Суббота
  text += "ℹ️ Если верхняя неделя:\n";
  text += "⏰ 16:30 - 17:50\n";
  text += "📖 Системы анализа данных\n";
  text += "🏫 212\n\n";
}

// ---- если из Excel вообще ничего не пришло ----
if (text === "📚 Расписание на завтра:\n\n") {
  text += "🎉 Завтра занятий нет";
}

return [{ json: { text } }];

let text = $json.output || "";

// --- 1. Убираем служебные блоки AI ---
text = text.replace(/\[Used tools:[\s\S]*?\]\s*/g, "");
text = text.replace(/Result:[\s\S]*?\}\]/g, "");
text = text.replace(/\[\{[\s\S]*?\}\]/g, "");

// --- 2. Превращаем HTML-ссылки в обычные ---
text = text.replace(
  /<a\s+href="([^"]+)"[^>]*>(.*?)<\/a>/gi,
  (_, url, label) => `${label}: ${url}`
);

// --- 3. Удаляем HTML полностью ---
text = text.replace(/<[^>]*>/g, "");

// --- 4. УБИВАЕМ Markdown (это главное) ---
text = text
  .replace(/[_*~`]/g, "")          // markdown символы
  .replace(/\[(.*?)\]\((.*?)\)/g, "$1: $2") // [text](url)
  .replace(/^>\s?/gm, "")          // blockquote
  .replace(/^\s*[-+]\s+/gm, "• ")  // списки
  .replace(/#{1,6}\s?/g, "");      // заголовки

// --- 5. Убираем символы, которые Telegram считает entity ---
text = text.replace(/[<>[\]{}()]/g, "");

// --- 6. Чистим "умные" кавычки (Telegram их иногда ломает)
text = text.replace(/[“”«»]/g, '"');

// --- 7. Убираем невидимые unicode-символы (LLM их любит)
text = text.replace(/[\u200B-\u200D\uFEFF]/g, "");

// --- 8. Нормализуем переносы
text = text.replace(/\n{3,}/g, "\n\n").trim();

// --- 9. Telegram имеет лимит 4096 символов
if (text.length > 4000) {
  text = text.slice(0, 4000) + "\n\n…(truncated)";
}

return {
  json: {
    text: text
  }
};

// Получаем все строки
const data = $input.all().map(i => i.json);

// Если вдруг пусто
if (!data.length) {
  return [{ json: { message: "Расписание пустое" } }];
}

// ---- ГРУППИРУЕМ ПО ДНЯМ ----
const schedule = {};

for (const row of data) {
  const day = row["День"] ?? "Не указан";

  if (!schedule[day]) {
    schedule[day] = [];
  }

  schedule[day].push(row);
}

// ---- СОРТИРУЕМ ПАРЫ ВНУТРИ ДНЯ ----
for (const day in schedule) {
  schedule[day].sort((a, b) => (a["Пара"] ?? 0) - (b["Пара"] ?? 0));
}

// ---- ФОРМИРУЕМ КРАСИВОЕ СООБЩЕНИЕ ----
let text = "📚 *Расписание занятий*\n\n";

for (const day in schedule) {
  text += `🗓 *${day}*\n`;

  for (const lesson of schedule[day]) {
    const num = lesson["Пара"] ?? "-";
    const time = lesson["Время"] ?? "-";
    const subject = lesson["Дисциплина"] ?? "-";
    const type = lesson["Тип"] ?? "-";
    const teacher = lesson["Преподаватель"] ?? "-";
    const room = lesson["Аудитория"] ?? "-";

    text += `*${num} пара* (${time})\n`;
    text += `📖 ${subject}\n`;
    text += `👨‍🏫 ${teacher} · ${type}\n`;
    text += `🏫 ауд. ${room}\n\n`;
  }

  text += "──────────────\n";
}

// Telegram ограничение
if (text.length > 4000) {
  text = text.slice(0, 4000) + "\n...\nСообщение обрезано";
}

return [
  {
    json: {
      message: text
    }
  }
];

function cleanObsidianTitle(title) {
    let result = String(title || '')
        .trim()
        .replace(/[<>:"/\\|?*\x00-\x1F]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();

    return result;
}

// В режиме Run for Each Item используем $input.item.json
let originalTitle = $input.item.json.title;

// Чистим title
let cleanTitle = cleanObsidianTitle(originalTitle);

// Возвращаем результат как объект для следующего узла
return {
    json: {
        cleanTitle: cleanTitle
    }
};

function cleanObsidian(title) {
    return title.replace(/\|/g, ''); // удаляем все | из строки
}


// В режиме Run for Each Item используем $input.item.json
let originalTitle = $json.output;

// Чистим title
let cleanTitle = cleanObsidian(originalTitle);

// Возвращаем результат как объект для следующего узла
return {
    json: {
        output: cleanTitle
    }
};

