// Берём текст из ноды AI Agent2
const inputText = $('AI Agent2').first().json.output

// Находим начало нужного раздела

const startMarker = '## 1.';
let startIndex = inputText.indexOf(startMarker);
if (startIndex === -1) throw new Error("Раздел не найден");

// Находим конец раздела по заголовку ## 2.
let endIndex = inputText.indexOf('## 2.', startIndex);
if (endIndex === -1) endIndex = inputText.length; // если нет следующего заголовка, берём до конца

// Берём текст раздела
const textSection = inputText.slice(startIndex, endIndex).trim();

// Возвращаем результат
return [{ json: { textToAudio: textSection } }];

const text = $input.first().json.textToAudio
const maxChunkLength = 3500;

function chunkText(str, maxLength) {
  const chunks = [];
  let start = 0;
  while (start < str.length) {
    let end = start + maxLength;
    if (end < str.length) {
      const lastSpace = str.lastIndexOf(' ', end);
      if (lastSpace > start) end = lastSpace;
    }
    chunks.push(str.slice(start, end).trim());
    start = end;
  }
  return chunks;
}

const chunks = chunkText(text, maxChunkLength);
return chunks.map(chunk => ({ json: { textChunk: chunk } }));
